// movieApi.js
import axios from "axios";

const BASE_URL = "https://www.kobis.or.kr/kobisopenapi/webservice/rest/movie";
const API_KEY = "d8e32f85c0227cc1338f9f4ac7cedb94"; // 발급받은 키로 바꿔주세요

export const searchMovies = async (movieName) => {
  try {
    const response = await axios.get(`${BASE_URL}/searchMovieList.json`, {
      params: {
        key: API_KEY,
        movieNm: movieName,
      },
    });

    return response.data.movieListResult.movieList; // 영화 리스트 반환
  } catch (error) {
    console.error("KOFIC API 호출 에러:", error);
    throw error;
  }
};
